"""Self-contained, dependency-free Cloudflare-style operator console assets."""

CONTROL_PLANE_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NOESIS Control Plane</title>
<style>
:root{color-scheme:dark;font:14px Inter,ui-sans-serif,system-ui,sans-serif;background:#0b0d12;color:#f3f4f6;--panel:#12151c;--panel2:#171b24;--line:#282e3a;--muted:#929aaa;--blue:#f6821f;--green:#2dd4bf;--amber:#fbbf24;--red:#fb7185}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 85% -20%,#273145 0,#0b0d12 38%);display:grid;grid-template-columns:248px 1fr}.rail{border-right:1px solid var(--line);padding:24px 16px;background:#0d1016}.brand{display:flex;gap:10px;align-items:center;margin:0 8px 32px;font-weight:750;letter-spacing:.02em}.mark{width:28px;height:28px;border-radius:8px;background:linear-gradient(135deg,#f6821f,#fbbf24);box-shadow:0 0 24px #f6821f55}.rail h4{color:#687183;text-transform:uppercase;font-size:10px;letter-spacing:.13em;margin:24px 10px 8px}.nav{display:block;padding:10px 11px;color:#cbd2df;border-radius:7px;text-decoration:none}.nav.active,.nav:hover{background:#202632;color:#fff}.nav.active{box-shadow:inset 2px 0 var(--blue)}.scope{margin:22px 8px 0;padding:12px;border:1px solid var(--line);border-radius:8px;background:#111720}.scope strong{display:block;font-size:12px}.scope small{color:var(--muted);line-height:1.5}.main{max-width:1440px;width:100%;padding:28px 34px 52px}.top{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:22px;margin-bottom:20px}.eyebrow{color:var(--blue);font-size:11px;text-transform:uppercase;letter-spacing:.12em;font-weight:700}.top h1{font-size:28px;margin:6px 0}.top p{color:var(--muted);margin:0}.top-actions{display:flex;gap:8px;align-items:center}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.card{grid-column:span 4;background:linear-gradient(180deg,#151922,#11141a);border:1px solid var(--line);border-radius:10px;padding:16px;min-height:150px;box-shadow:0 8px 30px #00000020}.card.wide{grid-column:span 8}.card.full{grid-column:1/-1}.card h2{font-size:14px;margin:0 0 14px}.card h3{font-size:12px;color:#dce2ec;margin:18px 0 8px}.status{font-weight:700;color:var(--green)}.status.warn{color:var(--amber)}.muted,small{color:var(--muted)}pre{white-space:pre-wrap;word-break:break-word;color:#b9f3cf;max-height:220px;overflow:auto;background:#0d1015;border:1px solid #202632;border-radius:6px;padding:9px;font-size:11px}.metric{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #202632}.metric:last-child{border-bottom:0}.metric b{font-size:12px}.pill{display:inline-block;border-radius:99px;padding:3px 7px;margin:2px;background:#123b36;color:#9ff5e8;font-size:11px}.pill.off{background:#3e2630;color:#ffb1bf}.pill.pending{background:#48371a;color:#fcd782}button{background:#f6821f;color:#111;border:0;border-radius:6px;padding:8px 11px;cursor:pointer;font-weight:700}button.secondary{background:#222936;color:#e6ebf4}button:disabled{background:#303744;color:#858e9f;cursor:not-allowed}input,textarea{background:#0d1118;border:1px solid #303744;border-radius:6px;color:#fff;padding:9px;width:100%;margin:5px 0 8px}label{display:block;color:#aeb6c5;font-size:12px}.model{border-top:1px solid #282e3a;padding:10px 0}.model strong{color:#fff}.approval{border-left:3px solid var(--amber);padding:10px;background:#211b10;color:#f5d98c;font-size:12px}.timeline{font-family:ui-monospace,monospace;color:#a9b3c5}.no-side-effect{color:var(--green)}@media(max-width:900px){body{display:block}.rail{display:none}.main{padding:20px}.card,.card.wide{grid-column:1/-1}}
</style></head>
<body>
<aside class="rail"><div class="brand"><div class="mark"></div><span>NOESIS</span></div><a class="nav active" href="#overview">Overview</a><a class="nav" href="#sessions">Sessions</a><a class="nav" href="#agents">Agents & workspaces</a><a class="nav" href="#providers">Providers</a><a class="nav" href="#policy">Policy & lineage</a><a class="nav" href="#runtime">Runtime telemetry</a><h4>Workspace</h4><div class="scope"><strong>local-default</strong><small>Loopback only<br>Zero external capabilities<br><span class="no-side-effect">No hidden side effects</span></small></div><h4>Security posture</h4><div class="scope"><strong>Private / guarded</strong><small>Gatekeeper required for writes<br>Model invocation is explicit<br>Audit is append-only</small></div></aside>
<main class="main" id="overview"><header class="top"><div><div class="eyebrow">Portable control plane · v1</div><h1>Agent operations</h1><p>Cloudflare-style workspace view for local-first sessions, capabilities and isolated runtimes. No session mutation endpoint is enabled by default unless the server receives an explicit session store.</p></div><div class="top-actions"><span id="updated" class="muted">Not loaded</span><button class="secondary" id="refresh">Refresh</button></div></header>
<div class="grid">
<section class="card"><h2>System health</h2><div id="health" class="status">Loading…</div><div class="metric"><span>Network boundary</span><b>loopback</b></div><div class="metric"><span>Control plane</span><b>local</b></div><pre id="health-detail"></pre></section>
<section class="card" id="providers"><h2>Provider health</h2><small>Models & capabilities</small><div id="models" class="status">Loading…</div><div id="model-list"></div><small>Invoke disabled in metadata mode. Calls require a versioned session and Gatekeeper approval path.</small></section>
<section class="card" id="policy"><h2>Policy & data lineage</h2><div class="approval">Pending actions are explainable before commit. Credentials remain outside child processes.</div><div class="metric"><span>Observed resources</span><b id="observed">0</b></div><div class="metric"><span>Outbound policy</span><b>deny by default</b></div><div class="metric"><span>Write policy</span><b>approval required</b></div><div class="metric"><span>Audit</span><b>append-only</b></div></section>
<section class="card wide" id="sessions"><h2>Sessions</h2><p class="muted">A session combines messages, durable state, bounded events and explicit provider/tool policy.</p><h3>Interactive workspace</h3><div id="session-status" class="status">Session API capability is detected from the response.</div><label>Owner<input id="owner" value="local-user" maxlength="80"></label><button id="create-session">Create session</button><label>Session ID<input id="session-id" placeholder="created session id"></label><button class="secondary" id="resume-session">Resume</button><label>Message<textarea id="message" rows="3" maxlength="12000" placeholder="Append a bounded message to the local session ledger"></textarea></label><button id="send-message">Append message</button><pre id="session-detail">No session selected.</pre><pre id="event-stream"></pre></section>
<section class="card" id="agents"><h2>Agents & workspaces</h2><div class="metric"><span>Claims</span><b>exclusive</b></div><div class="metric"><span>Workspace roots</span><b>per-agent</b></div><div class="metric"><span>Patch state</span><b>review-only</b></div><div class="metric"><span>Resume</span><b>durable</b></div><p class="muted">Topology data appears after a session or coordinator endpoint is available.</p></section>
<section class="card" id="runtime"><h2>Runtime telemetry</h2><div id="telemetry-status" class="status">Snapshot unavailable</div><div class="metric"><span>Active SSE streams</span><b id="active-streams">0</b></div><div class="metric"><span>Active child runtimes</span><b id="active-children">0</b></div><div class="metric"><span>Child execution</span><b>bounded</b></div><div class="metric"><span>Shell interpolation</span><b>disabled</b></div><div class="metric"><span>Network</span><b>fail-closed</b></div><div class="metric"><span>Python gate</span><b>3.14-only</b></div><pre id="telemetry-detail">No telemetry loaded.</pre><p class="muted">Telemetry is read-only, redacted and bounded. This process boundary is not claimed to be a VM-level sandbox.</p></section>
<section class="card full"><h2>Audit timeline</h2><div id="timeline" class="timeline">No events loaded.</div></section>
</div></main>
<script>
const text=(x)=>JSON.stringify(x,null,2);const esc=(x)=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let sessionId='';
function renderModels(records){const root=document.getElementById('model-list');root.innerHTML='';if(!records.length){root.textContent='No verified models; selector unavailable.';return;}records.forEach(model=>{const caps=model.capabilities||{};const keys=['tools','vision','structured_output','streaming','long_context'];const badges=keys.map(k=>'<span class="pill '+(caps[k]?'':'off')+'">'+esc(k)+': '+(caps[k]?'on':'off')+'</span>').join('');const row=document.createElement('div');row.className='model';row.innerHTML='<strong>'+esc(model.id)+'</strong> <small>'+esc(model.provider)+' · '+esc(model.status)+'</small><div>'+badges+'</div><button disabled>Invoke disabled</button>';root.appendChild(row);});}
async function load(path,target,detail){try{const r=await fetch(path,{cache:'no-store'});const data=await r.json();document.getElementById(target).textContent=data.status||'unknown';if(data.status==='degraded')document.getElementById(target).className='status warn';document.getElementById(detail).textContent=text(data.data||data.error||{});if(path==='/models')renderModels((data.data&&data.data.models)||[]);}catch(e){document.getElementById(target).textContent='unavailable';document.getElementById(detail).textContent='read failed: '+e.name;if(path==='/models')renderModels([]);}}
function renderTelemetry(data){const snapshot=(data&&data.telemetry)||{};const counters=snapshot.counters||{};document.getElementById('active-streams').textContent=String(counters.active_streams||0);document.getElementById('active-children').textContent=String(counters.active_children||0);document.getElementById('telemetry-detail').textContent=text(snapshot);document.getElementById('telemetry-status').textContent='SSE telemetry '+(snapshot.updated_at_epoch?'connected':'idle');}
async function loadTelemetry(){try{const r=await fetch('/api/telemetry',{cache:'no-store'});const data=await r.json();if(data.ok)renderTelemetry(data.data);else document.getElementById('telemetry-status').textContent='Telemetry '+(data.status||'unavailable');}catch(e){document.getElementById('telemetry-status').textContent='Telemetry unavailable';}}
function connectTelemetry(){if(!window.EventSource)return;const source=new EventSource('/api/telemetry/events');source.addEventListener('telemetry',event=>{try{renderTelemetry(JSON.parse(event.data).data);}catch(_e){}});source.onerror=()=>{document.getElementById('telemetry-status').textContent='SSE reconnect pending';source.close();setTimeout(connectTelemetry,3000);};}
async function refresh(){await Promise.all([load('/health','health','health-detail'),load('/models','models','health-detail'),loadTelemetry()]);document.getElementById('updated').textContent='Updated '+new Date().toLocaleTimeString();}
async function createSession(){const r=await fetch('/api/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({owner:document.getElementById('owner').value})});const data=await r.json();if(data.ok){sessionId=data.data.session.session_id;document.getElementById('session-id').value=sessionId;document.getElementById('session-status').textContent='Session '+sessionId+' ready';await resumeSession();}else document.getElementById('session-detail').textContent=text(data.error);}
async function resumeSession(){sessionId=document.getElementById('session-id').value.trim();if(!sessionId)return;const r=await fetch('/api/sessions/'+encodeURIComponent(sessionId),{cache:'no-store'});const data=await r.json();document.getElementById('session-detail').textContent=text(data.data||data.error);if(data.ok){const ev=await fetch('/api/sessions/'+encodeURIComponent(sessionId)+'/events',{cache:'no-store'});const raw=await ev.text();document.getElementById('event-stream').textContent=raw;document.getElementById('timeline').textContent=raw;}}
async function sendMessage(){if(!sessionId){document.getElementById('session-detail').textContent='Create or resume a session first.';return;}const content=document.getElementById('message').value;if(!content.trim())return;const r=await fetch('/api/sessions/'+encodeURIComponent(sessionId)+'/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:'user',content})});const data=await r.json();document.getElementById('session-detail').textContent=text(data);document.getElementById('message').value='';await resumeSession();}
document.getElementById('refresh').addEventListener('click',refresh);document.getElementById('create-session').addEventListener('click',createSession);document.getElementById('resume-session').addEventListener('click',resumeSession);document.getElementById('send-message').addEventListener('click',sendMessage);refresh();connectTelemetry();
</script></body></html>'''

__all__ = ["CONTROL_PLANE_HTML"]
